{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Do you supply internationally?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. VOCOM supports global fiber optic cable import and export for telecommunications, infrastructure, and data center projects worldwide. Shipping timelines vary depending on destination and order volume."
      }
    },
    {
      "@type": "Question",
      "name": "Can you handle bulk and wholesale cable orders?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. We specialize in bulk and wholesale fiber optic cable supply for large-scale infrastructure and telecom deployments, including custom project requirements."
      }
    },
    {
      "@type": "Question",
      "name": "Do you provide technical datasheets and specifications?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Technical datasheets and product specifications are available upon request for all standard fiber optic cable types and custom configurations."
      }
    },
    {
      "@type": "Question",
      "name": "What does Vocom International supply?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Vocom International supplies fiber optic cable and connectivity solutions, founded in 1998 with a focus on cross-Pacific and Asia-Pacific routes. We specify, source and deliver cable built to your requirements."
      }
    },
    {
      "@type": "Question",
      "name": "Who manufactures the cable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Cable is produced to specification by tier 1 manufacturing partners on Fujikura preform glass. Vocom handles specification, sourcing, build-to-order coordination and delivery."
      }
    },
    {
      "@type": "Question",
      "name": "What is the typical lead time?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Standard build-to-order programs run 6 to 8 weeks, and up to 10 weeks for high-count or custom builds. Confirm the date against your actual specification when you request a quote."
      }
    },
    {
      "@type": "Question",
      "name": "Is there an expedited option?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. An expedited program is available at 2 to 3 weeks, covering production and air freight."
      }
    },
    {
      "@type": "Question",
      "name": "Is there a minimum order quantity?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Order sizes depend on the construction and fiber count. Send us your specification and quantity and we will confirm any minimums with your quote."
      }
    },
    {
      "@type": "Question",
      "name": "Can you supply custom fiber counts and constructions?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Cable is built to order, so fiber count, construction and jacket can be specified to suit the route and the install method."
      }
    },
    {
      "@type": "Question",
      "name": "Which fiber type do I need: G.652D, G.657A1 or G.657A2?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "G.652D is the standard for outside plant and long-distance routes. G.657A1 and G.657A2 are bend-insensitive types for drops and indoor work, with A2 handling tighter bends. If you are unsure, send us the route details and we will recommend one."
      }
    },
    {
      "@type": "Question",
      "name": "Should I choose aerial or buried cable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It depends on span, terrain, make-ready cost and lead time. Aerial routes use self-supporting ADSS cable, while buried routes use armored direct burial or duct cable. Our blog guide on aerial versus buried outside plant fiber walks through the trade-offs."
      }
    },
    {
      "@type": "Question",
      "name": "What is rollable ribbon fiber and when is it used?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Rollable ribbon bonds fibers at intervals so the ribbon folds into a compact cylinder. It carries higher counts in a given duct than flat ribbon, and still supports mass fusion splicing. It is typically used for ultra-high-count data center and long-haul builds."
      }
    },
    {
      "@type": "Question",
      "name": "What is mass fusion splicing?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Mass fusion splicing joins a whole 12-fiber ribbon in one operation instead of one fiber at a time. On high-count cable this cuts splicing labor sharply, which is why ribbon constructions are common above a few hundred fibers."
      }
    },
    {
      "@type": "Question",
      "name": "Do you supply connectors and hardware?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. The catalog covers connectors and hardware alongside cable, including factory-terminated MTP/MPO trunks and break-out harnesses for data center builds."
      }
    },
    {
      "@type": "Question",
      "name": "Which fiber counts do you supply for data centers?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Data center builds typically range from hundreds of fibers at the edge to 864 and 1,728 in colocation and cloud, and higher counts for hyperscale. Ribbon and rollable ribbon constructions are available for the highest counts."
      }
    },
    {
      "@type": "Question",
      "name": "What test data and certifications are available?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Datasheets and test data are available on request. Tell us the standards your project requires and we will confirm what applies to your specification."
      }
    },
    {
      "@type": "Question",
      "name": "What delivery terms do you offer?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Delivery terms such as FOB or DDP can be quoted depending on the destination. Include the delivery location in your request and we will confirm."
      }
    },
    {
      "@type": "Question",
      "name": "How do I request a quote, and what should I include?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Use the contact page and include the cable type, fiber count, quantity, route or install method and delivery location. The more complete the specification, the faster we can confirm price and lead time."
      }
    },
    {
      "@type": "Question",
      "name": "What is fiber optic cable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fiber optic cable carries data as pulses of light through thin glass strands instead of electrical signals through copper. It supports far higher bandwidth and longer distances without signal loss, which is why it is the standard for telecommunications, data centers, and internet backbone infrastructure."
      }
    },
    {
      "@type": "Question",
      "name": "What is single mode fiber cable, and how is it different from multimode?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Single mode fiber uses a narrow glass core carrying one light path, built for long distance runs between buildings, across a campus, or between cities, typically specified as OS2 (G.652D or bend insensitive G.657). Multimode fiber uses a wider core and multiple light paths, built for shorter runs inside a building or data center row, typically OM3 or OM4. We supply both, build-to-order on Fujikura preform glass."
      }
    },
    {
      "@type": "Question",
      "name": "What is composite fiber optic cable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Composite fiber optic cable, also sold as copper fiber composite cable, puts optical fibers and copper conductors in one sheath, so a single pull carries both data and power to a remote site such as a camera, radio or sensor. Vocom supplies composite fiber cable build-to-order, with a standard lead time of 6 to 8 weeks and up to 10 weeks for custom builds."
      }
    },
    {
      "@type": "Question",
      "name": "Can Vocom be a second source for distributors?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Rollable ribbon, high-count, micro and indoor plenum cable are the specs most often quoted in months elsewhere. Send the spec and we return a price and a delivery date. Any spec can be built to order as a custom build."
      }
    },
    {
      "@type": "Question",
      "name": "Can orders be split across ship dates?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Large orders are commonly split into tranches so cable arrives against your customers' build phases instead of sitting in your yard."
      }
    },
    {
      "@type": "Question",
      "name": "Do you hold US stock?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Vocom is build-to-order with no US warehouse. Standard lead time is 6 to 8 weeks, expedited air freight is 2 to 3 weeks, and high-count or custom builds take up to 10 weeks."
      }
    },
    {
      "@type": "Question",
      "name": "I make duct or run a consultancy. Can I refer a customer?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Send the customer contact and what they are building, and we will quote it, build to order and deliver, with documentation and customs coordinated. HDPE microduct and vaults can be quoted alongside the cable."
      }
    }
  ]
}

